            ></v-progress-circular>
            <p class="mt-3">Loading your requests...</p>
          </v-card-text>
          <v-card-text v-else-if="!myRequests.length" class="text-center py-8">
            <v-icon size="64" color="grey lighten-1"
              >mdi-clipboard-outline</v-icon
            >
            <p class="mt-3 subtitle-1">
              You have not submitted any training requests yet.
            </p>
          </v-card-text>
          <v-card-text v-else class="pa-0">
            <v-data-table
              :headers="requestHeaders"
              :items="myRequests"
              :items-per-page="5"
              class="elevation-0"
            >
              <template v-slot:item.need="{ item }">
                <div class="font-weight-medium">{{ item.needTitle }}</div>
              </template>
              <template v-slot:item.type="{ item }">
                <v-chip
                  :color="getTrainingTypeColor(item.type)"
                  text-color="white"
                  small
                >
                  {{ item.typeDisplay }}
                </v-chip>
              </template>
              <template v-slot:item.status="{ item }">
                <v-chip
                  :color="getStatusColor(item.status)"
                  text-color="white"
                  small
                >
                  {{ item.statusDisplay }}
                </v-chip>
              </template>
              <template v-slot:item.actions="{ item }">
                <v-tooltip bottom>
                  <template v-slot:activator="{ on }">
                    <v-btn
                      icon
                      small
                      color="primary"
                      v-on="on"
                      @click="viewRequest(item)"
                    >
                      <v-icon small>mdi-eye</v-icon>
                    </v-btn>
                  </template>
                  <span>View Details</span>
                </v-tooltip>
                <v-tooltip
                  bottom
                  v-if="item.status === 'undersupervisorreview'"
                >
                  <template v-slot:activator="{ on }">
                    <v-btn
                      icon
                      small
                      color="orange"
                      v-on="on"
                      @click="editRequest(item)"
                    >
                      <v-icon small>mdi-pencil</v-icon>
                    </v-btn>
                  </template>
                  <span>Edit Request</span>
                </v-tooltip>
              </template>
            </v-data-table>
          </v-card-text>
        </v-card>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { eventBus } from "@/main";
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";
export default {
  name: "TrainingPlanRequest",
  mixins: [generalMixin, processQuestionnaire],
  props: ["queries"],
  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/ihris-training-plan-request",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/training-plan-request-profile",
      isEdit: true,
      overlay: false,
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      valid: false,
      submitting: false,
      loadingNeeds: true,
      loadingRequests: true,

      // User department
      userDepartment: null,
      userDepartmentName: "",

      // View and Filter
      page: 1,
      itemsPerPage: 15,
      searchQuery: "",
      selectedCadre: [],
      filteredNeeds: [],

      // Training Needs
      trainingNeeds: [],
      selectedNeed: null,
      incrementNeed: 0,

      trainingtype: "",
      duration: "",
      startDate: "",
      endDate: "",
      methodology: "",
      courselevel: null,
      course: null,
      courseother: "",
      institution: "",
      comments: "",

      // My Requests
      myRequests: [],
      requestHeaders: [
        { text: "Training Need", value: "need" },
        { text: "Type", value: "type" },
        { text: "Training Course/Program", value: "course" },
        { text: "Start Date", value: "startDate" },
        { text: "End Date", value: "endDate" },
        { text: "Status", value: "status" },
        { text: "Submitted", value: "submittedDate" },
        { text: "Actions", value: "actions", sortable: false },
      ],

      // Available filters
      availableCadres: [],
      financialYear: {},
    };
  },
  computed: {
    pagedNeeds() {
      var start = (this.page - 1) * this.itemsPerPage;
      return this.filteredNeeds.slice(start, start + this.itemsPerPage);
    },
    totalPages() {
      return Math.ceil(this.filteredNeeds.length / this.itemsPerPage);
    },
    needSlotProps() {
      return {
        source: {
          fromArray: true,
          path: "need",
          data: { reference: "Basic/" + this.selectedNeed.id },
        },
      };
    },
    hasActiveFilters() {
      return this.searchQuery || this.selectedCadre.length > 0;
    },

    approvedRequestsCount() {
      return this.myRequests.filter(function(request) {
        return request.status === "approved";
      }).length;
    },

    pendingRequestsCount() {
      return this.myRequests.filter(function(request) {
        return request.status === "pending";
      }).length;
    },
    rejectedRequestsCount() {
      return this.myRequests.filter(function(request) {
        return request.status === "rejected";
      }).length;
    },
    durationValidationMessage() {
      if (!this.startDate || !this.endDate || !this.trainingtype) {
        return null;
      }

      const startDate = this.$moment(this.startDate);
      const endDate = this.$moment(this.endDate);
      // const endFinancial = this.$moment(this.financialYear.end);
      const today = this.$moment().startOf("day");

      if (!startDate.isValid() || !endDate.isValid()) {
        return null;
      }

      if (startDate.isBefore(today)) {
        return "Start date can not be in the past";
      }

      // Check if start date is after end date
      if (startDate.isAfter(endDate)) {
        return "Start date can not be after End date";
      }

      // if (startDate.isAfter(endFinancial)) {
      //   return (
      //     "Start date can not be after the current financial year " +
      //     endFinancial.format("DD-MM-YYYY")
      //   );
      // }

      const durationMonths = endDate.diff(startDate, "months", true);
      const trainingType = this.trainingtype;

      switch (trainingType) {
        case "shortterm":
          if (durationMonths > 6) {
            return `Short-term training cannot exceed 6 months (selected duration: ${durationMonths.toFixed(
              1,
            )} months)`;
          }
          break;
        case "longterm":
          if (durationMonths <= 6) {
            return `Long-term training must be greater than 6 months (selected duration: ${durationMonths.toFixed(
              1,
            )} months)`;
          }
          break;
        // parttime - no validation needed (any duration allowed)
        default:
          return null;
      }

      return null;
    },

    isDurationValid() {
      if (!this.startDate || !this.endDate || !this.trainingtype) {
        return true; // Not enough data to validate
      }

      const startDate = this.$moment(this.startDate);
      const endDate = this.$moment(this.endDate);
      // const endFinancial = this.$moment(this.financialYear.end);
      const today = this.$moment().startOf("day");

      if (!startDate.isValid() || !endDate.isValid()) {
        return true;
      }

      if (startDate.isBefore(today)) {
        return false;
      }

      // Check if start date is after end date
      if (startDate.isAfter(endDate)) {
        return false;
      }

      // if (startDate.isAfter(endFinancial)) {
      //   return false;
      // }

      const durationMonths = endDate.diff(startDate, "months", true);
      const trainingType = this.trainingtype;

      switch (trainingType) {
        case "shortterm":
          return durationMonths <= 6;
        case "longterm":
          return durationMonths > 6;
        case "parttime":
          return true;
        default:
          return true;
      }
    },

    isOtherQualification() {
      if (!this.course) return false;
      const ref =
        typeof this.course === "object" ? this.course.reference : this.course;
      return ref === "Basic/otherqualificationname";
    },

    durationInMonths() {
      if (!this.startDate || !this.endDate) {
        return null;
      }

      const startDate = this.$moment(this.startDate);
      const endDate = this.$moment(this.endDate);

      if (!startDate.isValid() || !endDate.isValid()) {
        return null;
      }

      return endDate.diff(startDate, "months", true).toFixed(1);
    },
  },
  methods: {
    // Initialization methods
    async loadTrainingNeeds() {
      this.loadingNeeds = true;
      try {
        // this.userDepartment = this.$store.state.user.department;
        await this.getDepartmentName();

        // Fetch training needs
        var query = `?_profile=http://ihris.org/fhir/StructureDefinition/training-need-profile&department=${this.loggedInStaff.department.code}&facility=${this.loggedInStaff.facility}`;
        var response = await fetch("/fhir/Basic" + query);
        var results = await response.json();

        if (results && results.entry && results.entry.length > 0) {
          var self = this;
          this.trainingNeeds = await Promise.all(
            results.entry.map(async function(entry) {
              return await self.processTrainingNeed(entry.resource);
            }),
          );

          this.extractFilterOptions();
          this.filteredNeeds = this.trainingNeeds.slice();
        }
      } catch (error) {
        console.error("Error loading training needs:", error);
        this.showSnackbar("Error loading training needs", "error");
      } finally {
        this.loadingNeeds = false;
      }
    },

    async getDepartmentName() {
      try {
        // Simulate department name lookup
        this.userDepartmentName = "Human Resources";
      } catch (error) {
        console.error("Error getting department name:", error);
        this.userDepartmentName = "";
      }
    },

    async processTrainingNeed(resource) {
      var need = {
        id: resource.id,
        resourceRef: "Basic/" + resource.id,
        title: "Untitled Training Need",
        description: "No description available",
        cadres: [],
        funder: null,
        trainingTypes: [],
        priority: "Medium",
        startDate: null,
        endDate: null,
        created: resource.meta ? resource.meta.lastUpdated : null,
        applications: 0,
      };

      // Extract data from extensions
      if (resource.extension) {
        resource.extension.forEach(function(ext) {
          if (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
          ) {
            need.title = ext.valueString || need.title;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/description"
          ) {
            need.description = ext.valueString || need.description;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/cadre"
          ) {
            if (ext.valueCoding) {
              need.cadres.push(ext.valueCoding.display || ext.valueCoding.code);
            }
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/start-date"
          ) {
            need.startDate = ext.valueDate;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/end-date"
          ) {
            need.endDate = ext.valueDate;
          }
        });
      }

      // Get application count
      need.applications = await this.getNeedApplicationsCount(resource.id);

      return need;
    },

    async getNeedApplicationsCount(needId) {
      try {
        var query =
          "?_profile=http://ihris.org/fhir/StructureDefinition/training-plan-request-profile&trainingneed=Basic/" +
          needId +
          "&_summary=count";
        var response = await fetch("/fhir/Basic" + query);
        var results = await response.json();
        return results.total || 0;
      } catch (error) {
        console.error("Error counting applications:", error);
        return 0;
      }
    },

    extractFilterOptions() {
      var cadreSet = new Set();

      this.trainingNeeds.forEach(function(need) {
        need.cadres.forEach(function(cadre) {
          cadreSet.add(cadre);
        });
      });

      this.availableCadres = Array.from(cadreSet).map(function(cadre) {
        return {
          text: cadre,
          value: cadre,
        };
      });
    },

    // Filtering methods
    filterNeeds() {
      var self = this;
      var filtered = this.trainingNeeds.filter(function(need) {
        // Search filter
        if (self.searchQuery) {
          var query = self.searchQuery.toLowerCase();
          var matchesSearch =
            need.title.toLowerCase().includes(query) ||
            need.description.toLowerCase().includes(query) ||
            need.cadres.some(function(cadre) {
              return cadre.toLowerCase().includes(query);
            });
          if (!matchesSearch) return false;
        }

        // Cadre filter
        if (self.selectedCadre.length > 0) {
          var matchesCadre = self.selectedCadre.some(function(cadre) {
            return need.cadres.includes(cadre);
          });
          if (!matchesCadre) return false;
        }

        return true;
      });

      this.filteredNeeds = filtered;
    },

    resetFilters() {
      this.searchQuery = "";
      this.selectedCadre = [];
      this.filteredNeeds = this.trainingNeeds.slice();
    },

    // Need selection methods
    isNeedSelected(need) {
      return this.selectedNeed && this.selectedNeed.id === need.id;
    },

    toggleSelectNeed(need) {
      this.incrementNeed++;
      if (this.isNeedSelected(need)) {
        this.selectedNeed = null;
      } else {
        this.selectedNeed = need;
        var self = this;
        setTimeout(function() {
          self.scrollToForm();
        }, 300);
      }
    },

    deselectNeed() {
      this.selectedNeed = null;
    },

    scrollToForm() {
      var formSection = this.$refs.formSection;
      if (formSection) {
        formSection.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    },

    // UI helper methods
    getEmptyStateTitle() {
      return this.trainingNeeds.length === 0
        ? "No Training Needs Available"
        : "No Matching Training Needs";
    },

    getEmptyStateMessage() {
      return this.trainingNeeds.length === 0
        ? "There are currently no training needs identified for your department."
        : "Try adjusting your filters to see more results.";
    },

    getNeedIcon(need) {
      return this.isNeedSelected(need)
        ? "mdi-check-circle"
        : "mdi-circle-outline";
    },

    getDisplayCadres(cadres, limit) {
      limit = limit || 2;
      return cadres.slice(0, limit);
    },

    getNeedHeaderClass(need) {
      return this.isNeedSelected(need) ? "primary lighten-5" : "";
    },

    getNeedCardClass(need) {
      return this.isNeedSelected(need)
        ? "elevation-4 border-primary"
        : "elevation-1";
    },

    getNeedCardStyle(need) {
      var border = this.isNeedSelected(need)
        ? "2px solid #2196F3"
        : "1px solid #e0e0e0";
      return { border: border };
    },

    getSelectButtonText(need) {
      return this.isNeedSelected(need) ? "Selected" : "Select for Application";
    },

    // Color methods
    getPriorityColor(priority) {
      var colors = {
        High: "red",
        Medium: "orange",
        Low: "blue",
        high: "red",
        medium: "orange",
        low: "blue",
      };
      return colors[priority] || "grey";
    },

    getFunderColor(funder) {
      var colors = {
        Government: "blue lighten-5",
        Donor: "green lighten-5",
        "Self-funded": "yellow lighten-5",
        "Department Budget": "purple lighten-5",
      };
      return colors[funder] || "grey lighten-4";
    },

    getTrainingTypeColor(type) {
      var colors = {
        SHORT: "teal",
        LONG: "indigo",
        PARTTIME: "purple",
        "short-term": "teal",
        "long-term": "indigo",
        "part-time": "purple",
      };
      return colors[type] || "grey";
    },

    getStatusColor(code) {
      var colors = {
        DRAFT: "grey",
        PENDING: "orange",
        APPROVED: "green",
        REJECTED: "red",
        WITHDRAWN: "brown",
      };
      return colors[code] || "grey";
    },

    getNeedStatusColor(need) {
      var progress = this.getNeedProgress(need);
      if (progress > 75) return "success";
      if (progress > 50) return "warning";
      if (progress > 25) return "info";
      return "grey";
    },

    getNeedProgress(need) {
      var expected = 10;
      var actual = need.applications || 0;
      return Math.min((actual / expected) * 100, 100);
    },

    getNeedApplications(need) {
      return need.applications || 0;
    },

    // Date formatting methods
    formatDate(dateString, defaultValue) {
      if (!dateString) return defaultValue || "Not specified";
      try {
        var date = new Date(dateString);
        return date.toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        });
      } catch (error) {
        return defaultValue || "Invalid date";
      }
    },

    formatRelativeDate(dateString) {
      if (!dateString) return "";
      try {
        var date = new Date(dateString);
        var now = new Date();
        var diffDays = Math.floor((now - date) / (1000 * 60 * 60 * 24));

        if (diffDays === 0) return "Today";
        if (diffDays === 1) return "Yesterday";
        if (diffDays < 7) return diffDays + " days ago";
        if (diffDays < 30) return Math.floor(diffDays / 7) + " weeks ago";
        return this.formatDate(dateString);
      } catch (error) {
        return "";
      }
    },

    // My Requests methods
    async loadMyRequests() {
      this.loadingRequests = true;
      try {
        var practitionerId = this.queries.practitioner;

        if (!practitionerId) {
          this.loadingRequests = false;
          return;
        }

        var query =
          "?_profile=http://ihris.org/fhir/StructureDefinition/training-plan-request-profile&practitioner=Practitioner/" +
          practitionerId;
        var response = await fetch("/fhir/Basic" + query);
        var results = await response.json();

        if (results && results.entry && results.entry.length > 0) {
          var self = this;
          this.myRequests = results.entry.map(function(entry) {
            return self.processTrainingRequest(entry.resource);
          });
        }
      } catch (error) {
        console.error("Error loading my requests:", error);
        this.showSnackbar("Error loading your requests", "error");
      } finally {
        this.loadingRequests = false;
      }
    },

    processTrainingRequest(resource) {
      var request = {
        id: resource.id,
        needTitle: "Unknown",
        type: "",
        typeDisplay: "Unknown",
        course: "N/A",
        duration: "N/A",
        startDate: "",
        nedDate: "",
        status: "PENDING",
        statusDisplay: "Pending",
        submittedDate: "N/A",
      };

      // Extract data from resource
      if (resource.extension) {
        resource.extension.forEach(async (ext) => {
          if (
            ext.url ==
            "http://ihris.org/fhir/StructureDefinition/training-need-reference"
          ) {
            let needREf = ext.valueReference.reference;
            await fetch("/fhir/" + needREf).then(async (resp) => {
              let needRes = await resp.json();
              if (needRes.extension) {
                needRes.extension.forEach((needExt) => {
                  if (
                    needExt.url ==
                    "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                  ) {
                    request.needTitle = needExt.valueString || "Unknown";
                  }
                });
              }
            });
          }
          if (
            ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-type" &&
            ext.valueCoding
          ) {
            request.type = ext.valueCoding.code;
            request.typeDisplay =
              ext.valueCoding.display || ext.valueCoding.code;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/duration" &&
            ext.valueInteger
          ) {
            request.duration = ext.valueInteger + " months";
          } else if (
            ext.url ===
              "http://ihris.org/fhir/StructureDefinition/start-date" &&
            ext.valueDate
          ) {
            request.startDate = ext.valueDate;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/end-date" &&
            ext.valueDate
          ) {
            request.endDate = ext.valueDate;
          } else if (
            ext.url ===
              "http://ihris.org/fhir/StructureDefinition/request-status" &&
            ext.valueCoding
          ) {
            request.status = ext.valueCoding.code;
            request.statusDisplay =
              ext.valueCoding.display || ext.valueCoding.code;
          }
        });
      }

      if (resource.extension) {
        const qualNameExt = resource.extension.find(
          (e) =>
            e.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
        );
        request.course = qualNameExt?.valueString;
      }

      if (resource.meta && resource.meta.lastUpdated) {
        request.submittedDate = this.formatDate(
          resource.meta.lastUpdated.split("T")[0],
        );
      }

      return request;
    },

    // Form methods
    submitRequest: async function() {
      this.$refs.form.validate();
      if (!this.valid) return;
      this.submitting = true;
      this.overlay = true;
      try {
        await this.processFHIR();
        this.submitting = false;
        this.overlay = false;
        this.showSnackbar(
          "Training plan request submitted successfully!",
          "success",
        );
        this.clearForm();
        this.selectedNeed = null;
        this.submitting = false;
        this.overlay = false;
        await this.loadMyRequests();
      } catch (error) {
        console.log(error);
        this.submitting = false;
        this.overlay = false;
      }
    },

    clearForm() {
      if (this.$refs.form) {
        this.$refs.form.resetValidation();
      }
      this.fhirId = "";
      this.trainingtype = "";
      this.duration = "";
      this.startDate = "";
      this.endDate = "";
      this.methodology = "";
      this.courselevel = null;
      this.course = null;
      this.courseother = "";
      this.institution = "";
      this.comments = "";
    },

    // Navigation methods
    viewRequest(request) {
      this.$router.push(
        "/custom/training-plan-request-view?path=/lesotho/components/training&request=" +
          request.id,
      );
    },

    async editRequest(request) {
      this.selectedNeed = null;
      await fetch("/fhir/Basic/" + request.id).then(async (resp) => {
        let planReq = await resp.json();
        this.fhirId = planReq.id;
        let need = planReq.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-need-reference"
          );
        })?.valueReference?.reference;
        this.trainingtype = planReq.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-type"
          );
        })?.valueCoding?.code;
        this.duration = planReq.extension.find((ext) => {
          return (
            ext.url === "http://ihris.org/fhir/StructureDefinition/duration"
          );
        })?.valueInteger;
        this.startDate = planReq.extension.find((ext) => {
          return (
            ext.url === "http://ihris.org/fhir/StructureDefinition/start-date"
          );
        })?.valueDate;
        this.endDate = planReq.extension.find((ext) => {
          return (
            ext.url === "http://ihris.org/fhir/StructureDefinition/end-date"
          );
        })?.valueDate;
        this.methodology = planReq.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/learning-methodology"
          );
        })?.valueCoding?.code;
        this.courselevel = planReq.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/qualification-level"
          );
        })?.valueCoding?.code;
        this.course = planReq.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/qualification-name"
          );
        })?.valueReference;
        this.courseother = planReq.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/qualification-name-other"
          );
        })?.valueString;
        this.institution = planReq.extension.find((ext) => {
          return (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/planning-institution"
          );
        })?.valueString;
        this.comments = planReq.extension.find((ext) => {
          return (
            ext.url === "http://ihris.org/fhir/StructureDefinition/comments"
          );
        })?.valueString;
        this.toggleSelectNeed({ id: need.split("/")[1] });
      });
    },

    viewAllNeeds() {
      this.resetFilters();
      this.selectedNeed = null;
    },

    refreshData() {
      this.loadTrainingNeeds();
      this.loadMyRequests();
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },
    // Event handlers for FHIR components
    onTrainingTypeSelected(value) {
      this.trainingtype = value;
    },

    onStartDateSelected(value) {
      this.startDate = value;
    },

    onEndDateSelected(value) {
      this.endDate = value;
    },
  },

  watch: {
    trainingNeeds: {
      immediate: true,
      handler: function() {
        this.filterNeeds();
      },
    },
  },

  async created() {
    this.loadingRequests = true;

    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    if (!this.loggedInStaff.practitioner) {
      this.$store.commit("setMessage", {
        type: "error",
        text: "You are not a staff",
      });
      setTimeout(() => {
        this.$router.go(-1);
      }, 2000);
    }

    let response = await fetch("/site/leave/getFinancialYear");
    this.financialYear = await response.json();
    this.loadTrainingNeeds();
    this.loadMyRequests();
    eventBus.$on("Basic.type", (value) => {
      value = value?.split("#")[1];
      this.onTrainingTypeSelected(value);
    });

    // Listen for date changes
    eventBus.$on("Basic.startdate", (value) => {
      this.onStartDateSelected(value);
    });

    eventBus.$on("Basic.enddate", (value) => {
      this.onEndDateSelected(value);
    });

    eventBus.$on("Basic.course", (value) => {
      this.course =
        typeof value === "string" ? { reference: value } : value || null;
    });
    eventBus.$on("Basic.courselevel", (value) => {
      this.courselevel = value;
    });
    eventBus.$on("Basic.courseother", (value) => {
      this.courseother = value;
    });
  },

  components: {
    "fhir-choice": () => import("@/components/fhir/fhir-choice"),
    "fhir-string": () => import("@/components/fhir/fhir-string"),
    "fhir-date": () => import("@/components/fhir/fhir-date"),
    "fhir-reference": () => import("@/components/fhir/fhir-reference"),
    "ihris-questionnaire-section": () =>
      import("@/components/ihris/ihris-questionnaire-section"),
  },
};
</script>

